<?php require_once 'auth.php';require_admin();header('Content-Type: application/json');$pdo=db();$productId=(int)($_POST['product_id']??0);$materialId=(int)($_POST['material_id']??0);$sizeId=(int)($_POST['size_id']??0);$price=trim($_POST['price']??'');if(!$pdo||!$productId||!$materialId||!$sizeId||($price!==''&&!is_numeric($price))){http_response_code(422);exit;}try{if($price==='')$pdo->prepare('DELETE FROM product_variant_prices WHERE product_id=? AND material_id=? AND size_option_id=?')->execute([$productId,$materialId,$sizeId]);else $pdo->prepare('INSERT INTO product_variant_prices(product_id,material_id,size_option_id,price) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE price=VALUES(price)')->execute([$productId,$materialId,$sizeId,$price]);echo '{"ok":true}';}catch(Throwable $e){http_response_code(422);}
